def distribution(available, wish):
	double_keys = ['S,M', 'M,L', 'L,XL', 'XL,XXL', 'XXL,XXXL']
	double = {key: [] for key in double_keys}
	people = [''] * len(wish)
	for (i, w) in enumerate(wish):
		if w.count(',') == 0:
			if available[w] > 0:
				available[w] -= 1
				people[i] = w
			else:
				return ['NO']
		else:
			double[w].append(i)
	for key in double_keys:
		for p in double[key]:
			lack = True
			for size in key.split(','):
				if available[size] > 0:
					available[size] -= 1
					people[p] = size
					lack = False
					break
			if lack:
				return ['NO']
	return ['YES', people]

