def modinv(a, m):
	if a in memo:
		return memo[a]
	while a < 0:
		a += m
	(g, x, y) = egcd(a, m)
	if g != 1:
		raise Exception('Modular inverse does not exist')
	else:
		memo[a] = x % m
		return x % m
