		for j in house_members[i][2]:
			room_status[house_members[i][1]][2].append(j)
	move = True
	while move:
		move = False
		for i in range(n):
			if valid_move[i]:
				move = move or expand(i, room_sets, valid_move, room_status, edge_list)
	house_part = []
