						sm = self._op(self._d[right], sm)
						right -= 1
				return right + 1 - self._size
			sm = self._op(self._d[right], sm)
		return 0

	def _update(self, k: int) -> None:
		self._d[k] = self._op(self._d[2 * k], self._d[2 * k + 1])

class SparseTable:

	def __init__(self, v, op, e):
		self.N = len(v)
		self.op = op
		self.e = e
		self.lg = [self.e] * (self.N + 1)
		for i in range(2, self.N + 1):
			self.lg[i] = self.lg[i >> 1] + 1
		self.pow_2 = [pow(2, i) for i in range(20)]
		self.table = [None] * (self.lg[self.N] + 1)
		st0 = self.table[0] = [a for a in v]
		b = 1
		for i in range(self.lg[self.N]):
			st0 = self.table[i + 1] = [self.op(x, y) for (x, y) in zip(st0, st0[b:])]
			b <<= 1

	def prod(self, s, t):
		if s == t:
			return self.e
		b = t - s
		m = self.lg[b]
		return self.op(self.table[m][s], self.table[m][t - self.pow_2[m]])

