def union_set(u, v):
	up = find_set(u)
	vp = find_set(v)
	if ranks[up] > ranks[vp]:
		parent[vp] = up
	elif ranks[up] < ranks[vp]:
		parent[up] = vp
	else:
		parent[up] = vp
		ranks[vp] += 1

