from collections import defaultdict

def eval(A, dictR, r):
	l = dictR[r]
	nbToChange = 0
	newVal = A[l[-1]]
	for iR in range(l[-1], len(A) - 1):
		newVal += r
		if newVal != A[iR + 1]:
			nbToChange += 1
	lastVal = newVal
	newVal = A[l[0]]
	for iR in range(l[0], 0, -1):
		newVal -= r
		if newVal != A[iR - 1]:
			nbToChange += 1
	return (newVal, r, lastVal, nbToChange)

def solve(A, K):
