def f(arr, c):
	n = len(arr)
	total = 0
	start = []
	for i in range(n):
		start.append(arr[i] + (i + 1))
		arr[i] += min(i + 1, n - i)
	sorted_arr = sorted(arr)
	pref = [sorted_arr[0]]
	for i in range(1, n):
