	def diagonal(self, root):
		if root is None:
			return
		out = []
		node = root
		left_q = deque()
		while node:
			out.append(node.data)
			if node.left:
				left_q.appendleft(node.left)
			if node.right:
				node = node.right
			elif len(left_q) >= 1:
				node = left_q.pop()
