import math

def diff(root, res):
	if root is None:
		return (math.inf, res)
	if not root.left and (not root.right):
		return (root.data, res)
	(min_left, res) = diff(root.left, res)
	(min_right, res) = diff(root.right, res)
	min_node = min(min_left, min_right)
	res = max(res, root.data - min_node)
	return (min(min_node, root.data), res)

def maxDiff(root):
	res = -math.inf
	(_, res) = diff(root, res)
	return res

import math

def remove(lst, index):
	assert lst
	tail = len(lst) - 1
	(lst[index], lst[tail]) = (lst[tail], lst[index])
	lst.pop()

def swap_min(lst):
	if not lst:
		return
	argmin = min(range(len(lst)), key=lambda i: lst[i])
	(lst[0], lst[argmin]) = (lst[argmin], lst[0])

def find_primes(top):
	candidates = list(range(2, top))
	primes = []
	while candidates:
		latest_prime = candidates[0]
		primes.append(latest_prime)
		remove(candidates, 0)
		for i in range(len(candidates) - 1, -1, -1):
			if candidates[i] % latest_prime == 0:
				remove(candidates, i)
		swap_min(candidates)
	return primes

def find_prime_factor(n, primes):
	for p in primes:
		if n % p == 0:
			return p

def div4(n, primes, setprimes):
	if n <= 3:
		return 0
	elif n in setprimes:
		return 0
	else:
		p1 = find_prime_factor(n, primes)
		if p1 is None:
			return 0
		p2 = find_prime_factor(n // p1, primes)
		if p2 is None:
			p2 = n // p1
		if p1 * p2 == n and p1 != p2:
			return (1 + p1) * (1 + p2)
		elif p1 ** 3 == n:
			return (1 + p1) * (1 + p1 ** 2)
		else:
			return 0

def sum_four_divisors(arr):
	top = math.ceil(math.sqrt(max(arr) + 5))
	primes = find_primes(top)
	setprimes = set(primes)
	return sum((div4(elem, primes, setprimes) for elem in arr))

