class Solution:

	def primeProduct(self, L, R):

		def fun(n):
			primes = [1] * (n + 1)
			primes[0] = 0
			primes[1] = 0
			for i in range(2, n + 1):
				if primes[i] == 1:
					for j in range(i + i, n + 1, i):
						primes[j] = 0
			op = []
			for i in range(2, n + 1):
				if primes[i] == 1:
					op.append(i)
			return op
		mul = fun(int(R ** 0.5))
		dum = [1] * (R - L + 1)
		for i in mul:
			fm = L // i * i
			if fm < L:
				fm += i
			if fm <= 3:
				fm += fm
				dum[0] = 0
			for j in range(fm, R + 1, i):
				dum[j - L] = 0
		op = []
		pro = 1
		for i in range(L, R + 1):
			if dum[i - L] == 1:
				pro *= i
				op.append(i)
		return pro % (10 ** 9 + 7)

