def countTriplets(head, x):
	if head == None:
		return
	temp1 = head
	answer = []
	while temp1:
		hashmap = {}
		temp2 = temp1.nxt
		while temp2:
			value = x - (temp1.val + temp2.val)
			if value in hashmap:
				answer.append([temp1.val, temp2.val, value])
			else:
				hashmap[temp2.val] = 1
			temp2 = temp2.nxt
		temp1 = temp1.nxt
	return len(answer)

