def miller_rabin(p):
	if p == 2 or p == 3:
		return True
	if p < 3 or p % 2 == 0:
		return False
	for i in range(1):
		rand = randrange(2, p - 2)
		n = p - 1
		while n % 2 == 0:
			n //= 2
		mod = pow(rand, n, p)
		if mod == 1 or mod == p - 1:
			continue
		flag = 0
		while n != p - 1:
			mod = pow(rand, n, p)
			if mod == p - 1:
				flag = 1
				break
			n *= 2
		if flag == 0:
			return 0
	return True

