def root_path(bottom):
	chain = []
	while bottom is not None:
		chain.append(bottom)
		bottom = bottom.parent
	return chain

def height(bottom, top):
	res = 1
	while bottom != top and bottom is not None:
		bottom = bottom.parent
		res += 1
	return res

def q2(arr, nodes):
	(a, b) = arr
	first = nodes[a - 1]
	last = nodes[b - 1]
	path = root_path(last)
	h = height(last, first)
	res = 0
	while len(path) > 0:
		h = min(h, len(path))
		d = max(len(path) - h, 0)
		c = path.pop()
		for u in c.update:
			for i in range(h):
				res += (u[0] + (d + i) * u[1]) % (10 ** 9 + 7)
	return res % (10 ** 9 + 7)

def isRootBetween(bottom, top):
	if bottom == top:
