				self.tsum[par] = self.tsum[i] + self.tsum[i ^ 1]
				self.tmin[par] = min(self.tmin[i], self.tmin[i ^ 1] + self.tsum[i])
				self.tmax[par] = max(self.tmax[i], self.tmax[i ^ 1] + self.tsum[i])
