	def minJumps(self, arr, n):
		curend = 0
		curfar = 0
		ans = 0
		for i in range(n):
			curfar = max(curfar, i + arr[i])
			if curfar >= n - 1:
				ans += 1
				break
			if i == curend:
				ans += 1
				curend = curfar
			if curfar <= i:
				break
		if curfar < n - 1:
