def dec(s):
	return '{:b}'.format(s).count('1') - 1 if s else 0

def compute(head, *tail):
	hc = dec(head)
	if tail:
		(last, d) = compute(*tail)
		new = []
		d_ = d
		for (k, v) in last:
			if all((t & head == 0 for t in k)):
				x = v + hc
				d_ += x
				new.append((k + (head,), x))
			else:
				A = tuple((t for t in k if t & head == 0))
				b = reduce(or_, (t for t in k if t & head != 0), head)
				x = dec(sum(A) + b) - len(A)
				d_ += x
				new.append((A + (b,), x))
		new_ = new + last
		return (new_, d_)
	else:
		return ([((), 0), ((head,), hc)], hc)
