primes = []
factors = []

def factorize(M):
	factors.clear()
	for i in range(0, len(primes)):
		if M == 1:
			break
		if M % primes[i] == 0:
			cnt = 0
			while M % primes[i] == 0:
				cnt = cnt + 1
				M = M / primes[i]
			factors.append(tuple([primes[i], 2 * cnt]))
	if M != 1:
		factors.append(tuple([M, 2]))
	return
ans = []

def solve(idx, val, threshold):
	if idx == len(factors):
		if val >= threshold:
			ans.append(val)
		return
	cnt = factors[idx][1]
	fact = factors[idx][0]
	mul = fact
	solve(idx + 1, val, threshold)
	for i in range(1, cnt + 1):
		solve(idx + 1, val * mul, threshold)
		mul = mul * fact

