import sys, math, re
from collections import defaultdict, deque
testing = [False]

def build_match_remover(subs):
	subs2 = []
	charToRep = {}
	for kw in subs:
		kwchars = set(kw)
		if len(kwchars) == 1:
			k = charToRep.get(kw[0])
			charToRep[kw[0]] = len(kw) if k is None else min(len(kw), k)
		else:
			subs2.append([kw, kwchars, None])
	for (c, k) in charToRep.items():
		subs2.append([c * k, {c}, None])
	subs = subs2
	subs.sort(key=lambda x: len(x[0]), reverse=True)
	for sub in subs:
		clause = re.escape(sub[0])
		sub[2] = re.compile('(?=({}))'.format(clause))

	def process(code):
		n = len(code)
		chars = set(code)
		exclude = [False] * n
		imin = 0
		for (ipat, sub) in enumerate(subs):
			if not sub[1] <= chars:
				continue
			(kw, pat) = (sub[0], sub[2])
			lastMatchEnd = 0
			istart = max(0, imin - len(kw))
			for match in pat.finditer(code[istart:]):
				(i1, i2) = (max(lastMatchEnd, match.start(1)), match.end(1))
				exclude[istart + i1:istart + i2] = [True] * (i2 - i1)
				lastMatchEnd = i2 - 1
			while imin < n and exclude[imin]:
				imin += 1
			if imin == n:
				break
		return ''.join([c for (i, c) in enumerate(code) if exclude[i] == False])
	return process

def remove_matches(process, srcs):
	return [process(s) for s in srcs]

def test_remove_matches():
	print('Testing remove_matches')
	for (srcs, subs, eans) in [[['11110111101111101110'], ['111', '11110'], ['0']]]:
		remover = build_match_remover(subs)
		ans = remove_matches(remover, srcs)
		if ans != eans:
			print('FAIL: {}: {}/{}: Expected {}, got {}'.format('remove matches', srcs, subs, eans, ans))

