def frobenius_rr(a):
	a.sort()
	k = len(a)
	a1 = a[0]
	n = [0] + [math.inf] * (a1 - 1)
	for i in range(1, k):
		d = math.gcd(a1, a[i])
		for r in range(0, d):
			nmin = min([n[q] for q in range(r, r + a1, d)])
			if nmin < math.inf:
				for _ in range(a1 // d):
					nmin = nmin + a[i]
					p = nmin % a1
					nmin = min(nmin, n[p])
					n[p] = nmin
	return max(n) - a1

def frobenius_bfd(a):
	a.sort()
	n = len(a)
	a1 = a[0]
	(Q, Qset) = (deque(), set())
	Q.append(0)
	Qset.add(0)
	P = [n - 1] * a1
	S = [0] + [a[0] * a[n - 1]] * (a1 - 1)
	Amod = [x % a1 for x in a]
	while Q:
		v = Q.popleft()
		Qset.remove(v)
		for j in range(1, P[v] + 1):
			u = v + Amod[j]
			if u >= a1:
				u -= a1
			w = S[v] + a[j]
			if w == S[u]:
				if j < P[u]:
					P[u] = j
			elif w < S[u]:
				S[u] = w
				P[u] = j
				if u not in Qset:
					Q.append(u)
					Qset.add(u)
	return max(S) - a1

