	def longestSubsequence(self, a, n):
		dp = [float('inf')] * (n + 1)
		dp[0] = float('-inf')
		max_len = 0
		for num in a:
			left = 0
			right = max_len
			while left <= right:
				mid = (left + right) // 2
				if dp[mid] < num:
					left = mid + 1
