	def solve_memo(self, n, F):
		if n < 0:
			return -1
		if n <= 3:
			return n
		if F[n] != -1:
			return F[n]
		mini = n
		temp = int(sqrt(n) + 1)
		for i in range(1, temp):
			if i * i > n:
				break
			ans = 1 + self.solve_memo(n - i * i, F)
			mini = min(mini, ans)
		F[n] = mini
		return F[n]

	def MinSquares(self, n):
		F = [-1] * (n + 1)
		return self.solve_memo(n, F)

