def printKDistantfromLeaf(root, k):
	lis = []
	se = set()

	def fun(root):
		if root == None:
			return
		lis.append(root)
		if root.left == None and root.right == None:
			dis = len(lis) - k - 1
			if dis >= 0:
				se.add(lis[dis])
			lis.pop()
			return
		fun(root.left)
		fun(root.right)
		lis.pop()
	fun(root)
	return len(se)

