import sys

def facmod(n):
	r = 1
	for i in range(1, n + 1):
		r *= i
		r %= P
	return r

def invmod(n):
	return pow(n, P - 2, P)

def binmod(n, k):
	return facmod(n) * invmod(facmod(k) * facmod(n - k) % P) % P

def chose(n, k):
	return binmod(n + k - 1, k - 1)
