def grundy(g):
	if g in gdic:
		return gdic[g]
	lg = len(g)
	subg = set()
	for (ln, w) in words:
		pos = g.find(w)
		while pos >= 0:
			gpre = grundy(g[:pos])
			gpost = grundy(g[pos + ln:])
			subg.add(gpre ^ gpost)
			pos = g.find(w, pos + 1)
	if len(subg) == 0:
		gdic[g] = 0
	else:
		mex = 0
		while mex in subg:
			mex += 1
		gdic[g] = mex
	return gdic[g]
