import sys

def roadToCinema(V, S, T, stations):
	m = len(stations)
	t = 0
	stations.append(S)
	prev = 0
	for cur in stations:
		dis = cur - prev
		if dis > V:
			return False
		else:
			t += max(dis * 3 - V, dis)
		if t > T:
			return False
		prev = cur
	return True

def binSearch(S, T, stations):
	l = 0
	r = S * 2
	if T < S:
		return float('inf')
	while l + 1 < r:
		m = l + (r - l) // 2
		if roadToCinema(m, S, T, stations) == True:
			r = m
		else:
			l = m
	return r

