import math

def make_square(n):
	a = n ** 0.5 // 2
	j = int(n ** 0.5)
	while a <= j:
		temp = n - a * a
		k = temp ** 0.5
		if math.ceil(k) == int(k):
			return (int(k), int(a))
		a += 1
	return (-1,)

def solve(n):
