class Fenwick(object):

	def __init__(self, n):
		self.n = n
		self.a = [10 ** 9 for i in range(n)]
		self.w = 10 ** 9

	def zag(self, i, zn):
		self.w = min(self.w, zn)
		while i < self.n:
			self.a[i] = min(self.a[i], zn)
			i = i | i + 1

	def pol(self, r):
		ans = 10 ** 9
		while r >= 0:
			if ans > self.a[r]:
				ans = self.a[r]
			if ans == self.w:
				break
			r = (r & r + 1) - 1
		return ans
