class Solution:

	def correctBST(self, root):
		mid = first = last = None
		prev = None

		def inorder(root):
			if root is None:
				return
			inorder(root.left)
			nonlocal mid, first, last, prev
			if prev != None and root.data < prev.data:
				if first == None:
					first = prev
					mid = root
				else:
					last = root
			prev = root
			inorder(root.right)
		inorder(root)
		if first != None and last != None:
			(first.data, last.data) = (last.data, first.data)
		else:
			(first.data, mid.data) = (mid.data, first.data)
		return root

