def coords(d, n):
	(x, y) = (0, 0)
	for i in range(n):
		sect = 2 ** i
		sx = d >> 1 & 1
		sy = (d ^ sx) & 1
		(x, y) = rotate(x, y, sx, sy, sect)
		x += sect * sx
		y += sect * sy
		d //= 4
	return (x, y)

def rotate(x, y, sx, sy, n):
	if sy == 0:
		if sx == 1:
			(x, y) = (n - 1 - x, n - 1 - y)
		(x, y) = (y, x)
	return (x, y)
