	def longestPalindrome(self, s):
		size = len(s)
		if size <= 1 or s == s[::-1]:
			return s
		(start, maxlen) = (0, 1)
		for idx in range(1, size):
			add2 = s[idx - maxlen - 1:idx + 1]
			if idx - maxlen - 1 >= 0 and add2 == add2[::-1]:
				start = idx - maxlen - 1
				maxlen += 2
				continue
