class Solution:

	def countBits(self, n: int) -> int:
		k = 1
		su = 0
		while n // 2 ** (k - 1) > 0:
			d = n % 2 ** k
			rep = n // 2 ** k
			rep = rep * 2 ** (k - 1)
			if d + 1 - 2 ** (k - 1) > 0:
				su = su + rep + (d + 1 - 2 ** (k - 1))
			else:
				su += rep
			k += 1
		return su

