class Solution:

	def lemonadeChange(self, N, bills):
		d = {5: 0, 10: 0, 20: 0}
		for i in bills:
			if i == 5:
				d[i] += 1
			if i == 10:
				if d[5] > 0:
					d[i] += 1
					d[5] -= 1
				else:
					return False
			if i == 20:
