p = 998244353

def bsgs(g, h):
	N = ceil(sqrt(p - 1))
	tbl = {pow(g, i, p): i for i in range(N)}
	c = pow(g, N * (p - 2), p)
	for j in range(N):
		y = h * pow(c, j, p) % p
		if y in tbl:
			return j * N + tbl[y]

def gcd(a, b):
	return b if a % b == 0 else gcd(b, a % b)

def xgcd(a, b):
	(x0, x1, y0, y1) = (0, 1, 1, 0)
	while a != 0:
		(q, b, a) = (b // a, a, b % a)
		(y0, y1) = (y1, y0 - q * y1)
		(x0, x1) = (x1, x0 - q * x1)
	return (b, x0, y0)

def inv(a, m):
	(g, x, y) = xgcd(a, m)
	if g != 1:
		return None
	return (x + m) % m

def div(a, b, m):
	k = gcd(b, m)
	if a % k != 0:
		return None
	ak = a // k
	bk = b // k
	mk = m // k
	inv_bk = inv(bk, mk)
	return ak * inv_bk % mk

def matmul(A, B):
	m = len(A)
	C = [[0 for _ in range(m)] for _ in range(m)]
	for i in range(m):
		for k in range(m):
			for j in range(m):
				C[i][j] += A[i][k] * B[k][j] % (p - 1)
	for i in range(m):
		for j in range(m):
			C[i][j] %= p - 1
	return C

def Id(n):
	return [[int(i == j) for i in range(n)] for j in range(n)]

def matexp(A, n):
	if n == 0:
		return Id(len(A))
	h = matexp(A, n // 2)
	R = matmul(h, h)
	if n % 2 == 1:
		R = matmul(A, R)
	return R

