def solve(A):
	if A[0] != '?' and A[0] != '0':
		return 0
	if len(A) == 1:
		return 1
	B = {0: 0}
	for x in range(1, len(A)):
		if A[x] != '?':
			B[x - 1] = x - int(A[x])
	B[len(A) - 1] = len(A) - 1
	B_ind = []
	for b in B:
		if B[b] > b:
			return 0
		B_ind.append(b)
	B_ind.sort()
	for x in range(1, len(B_ind)):
		if B[B_ind[x]] < B[B_ind[x - 1]]:
			return 0
	result = 1
	for x in range(1, len(B_ind)):
