def pb(s):
	if mono_str(s):
		return mono_str_result(s)
	output = 0
	odd = [[], {}, 1]
	for c in s:
		if c not in odd[1]:
			odd[1][c] = 0
		odd[1][c] += 1
	for i in range(len(s)):
		odd[0].append(i)
	output += calc_palin_borders(odd[1])
	even = [[], {}, 1]
	for i in range(len(s) - 1):
		if s[i] == s[i + 1]:
			even[0].append(i)
			ss = s[i:i + 2]
			if ss not in even[1]:
				even[1][ss] = 0
			even[1][ss] += 1
	output += calc_palin_borders(even[1])
	for l in range(3, len(s)):
		if l % 2 == 0:
			wt = even
		else:
			wt = odd
		new_tuple = [[], {}, l]
		for idx in wt[0]:
			if idx - 1 >= 0 and idx + l - 2 < len(s) and (s[idx - 1] == s[idx + l - 2]):
				new_tuple[0].append(idx - 1)
				ss = s[idx - 1:idx - 1 + l]
				if ss not in new_tuple[1]:
					new_tuple[1][ss] = 0
				new_tuple[1][ss] += 1
		output += calc_palin_borders(new_tuple[1])
		output %= 1000000007
		if l % 2 == 0:
			even = new_tuple
		else:
			odd = new_tuple
	return output
