class Solution:

	def smallestDivisor(self, nums: List[int], threshold: int) -> int:
		if len(nums) == 1:
			return int(math.ceil(nums[0] / threshold))
		np_nums = np.array(nums)
		(low, high) = (1, np.max(np_nums))
		divisors = []
		while low + 1 < high:
			mid = (low + high) // 2
			if np.sum(np.ceil(np_nums / mid)) > threshold:
				low = mid
			else:
				high = mid
		if np.sum(np.ceil(np_nums / low)) <= threshold:
			return low
		return high

class Solution:

	def optimalSearchTree(self, keys, freq, n):
		dp = [[0 for i in range(n)] for j in range(n)]
		for g in range(n):
			for (i, j) in zip(range(n - g), range(g, n)):
				if g == 0:
					dp[i][j] = freq[i]
				if g == 1:
					dp[i][j] = min(2 * freq[i] + freq[j], 2 * freq[j] + freq[i])
				else:
					mini = 99999999999999
					sumi = 0
					for x in range(i, j + 1):
						sumi += freq[x]
					for k in range(i, j + 1):
						left = 0 if k == i else dp[i][k - 1]
						right = 0 if k == j else dp[k + 1][j]
						if left + right + sumi < mini:
							mini = left + right + sumi
					dp[i][j] = mini
		return dp[0][n - 1]

