import sys, heapq
(_BLANCO, _GRIS, _NEGRO) = (0, 1, 2)
_OO = int(1e+18)

class Regla:

	def __init__(self, id, diamantes, deMonstruo, monstruos):
		self.id = id
		self.diamantes = diamantes
		self.deMonstruo = deMonstruo
		self.monstruos = monstruos

	def clonar(self):
		return Regla(self.id, self.diamantes, self.deMonstruo, self.monstruos[:])

def esUnaMalaRegla(r, d):
	for m in r.monstruos:
		if d[m] == _OO:
			return True
	return False

def dfsVisit(u, color, reglas, diamMax, d):
	color[u] = _GRIS
	for r in reglas[u]:
		if esUnaMalaRegla(r, d):
			continue
		sumaMax = r.diamantes
		for v in r.monstruos:
			if color[v] == _BLANCO:
				dfsVisit(v, color, reglas, diamMax, d)
				if diamMax[v] > 0:
					sumaMax += diamMax[v]
			elif color[v] == _GRIS:
				diamMax[v] = -2
			elif color[v] == _NEGRO:
				sumaMax += diamMax[v]
			if diamMax[v] == -2:
				diamMax[u] = -2
				color[u] = _NEGRO
				return
		diamMax[u] = max(diamMax[u], sumaMax)
	color[u] = _NEGRO

def dfs(reglas, d):
	n = len(reglas)
	(color, diamMax) = ([], [])
	for i in range(n):
		color.append(_BLANCO)
		diamMax.append(0)
	for u in range(n):
		if color[u] == _BLANCO:
			dfsVisit(u, color, reglas, diamMax, d)
	return diamMax

def dijkstra(reglas, s, m, perteneceA):
	n = len(reglas)
	d = []
	(Q, visto) = ([], [])
	(k, sumaMin) = ([0] * m, [])
	for u in range(n):
		d.append(_OO)
		visto.append(False)
		for r in reglas[u]:
			sumaMin.append(0)
			k[r.id] = len(r.monstruos)
	d[s] = 0
	Q.append((0, s))
	heapq.heapify(Q)
	while len(Q) != 0:
		u = heapq.heappop(Q)[1]
		if visto[u]:
			continue
		visto[u] = True
		for p in perteneceA[u]:
			r = reglas[p[0]][p[1]]
			ocurrencias = p[2]
			k[r.id] -= ocurrencias
			sumaMin[r.id] += d[u] * ocurrencias
			if k[r.id] == 0 and d[r.deMonstruo] > sumaMin[r.id] + r.diamantes:
				d[r.deMonstruo] = sumaMin[r.id] + r.diamantes
				heapq.heappush(Q, (d[r.deMonstruo], r.deMonstruo))
	return d

