	def Bsearch(self, n, h, cost):
		l = 0
		r = 0
		for e in h:
			r = max(r, e)
		for e in h:
			l = min(l, e)
		lc = 0
		pc = 0
		ans = 0
		while l <= r:
			mid = (l + r) // 2
			lc = self.total_cost(mid - 1, h, cost)
