def lis(a):
	n = len(a)
	INF = float('inf')
	d = [INF] * (n + 1)
	d[0] = -INF
	for i in range(n):
		j = bisect_right(d, a[i])
		if d[j - 1] <= a[i] < d[j]:
			d[j] = a[i]
	ans = 0
	for i in range(n + 1):
		if d[i] < INF:
			ans = i
	return ans
