	Val = [[] for _ in range(N)]
	for (i, (_, _, c)) in enumerate(ABC):
		Val[Tmp[i]].append(c)
	q = []
	S = K
	for (i, (a, b, _)) in enumerate(ABC):
		vacant = S - a
		if vacant < 0:
			return -1
		while len(q) > vacant:
			hp.heappop(q)
		S += b
		for p in Val[i]:
			hp.heappush(q, p)
	while len(q) > S:
		hp.heappop(q)
	return sum(q)
