			self.insert_between(new_node, node.prev, node)
		elif index == len_:
			self.insert_between(new_node, sentinel.prev, sentinel)
		else:
			raise IndexError
		self.__len += 1

	def insert_between(self, node, left_node, right_node):
		if node and left_node and right_node:
			node.prev = left_node
			node.next = right_node
