INF = 10 ** 9

def Dijkstra(graph, start, m):
	dist = [INF] * len(graph)
	parent = [INF] * len(graph)
	queue = [(0, start)]
	while queue:
		(path_len, v) = heapq.heappop(queue)
		if dist[v] == INF:
			dist[v] = path_len
			for w in graph[v]:
				if dist[w[0]] == INF:
					parent[w[0]] = [v, w[1]]
					heapq.heappush(queue, (dist[v] + 1, w[0]))
	return (dist, parent)
