def solve(x, n):
	p0 = 0
	ret = []
	for (a, b) in x:
		ret += [a - p0 - 1]
		ret += [b]
		p0 = a
	ret += [n - p0]
	pp = getPLens(ret)
	cmlen = [0]
	for (i, z) in enumerate(ret):
		if i % 2 == 0:
			cmlen += [cmlen[-1] + z]
		else:
			cmlen += [cmlen[-1] + 1]
	rr = 0
	for (i, p) in enumerate(pp):
		if i % 2 == 0:
