def deleteNode(root, X):
	if not root:
		return None
	if X < root.data:
		root.left = deleteNode(root.left, X)
	elif X > root.data:
		root.right = deleteNode(root.right, X)
	else:
		if root.left is None and root.right is None:
			return None
		elif not root.left:
			current = root.right
			root = None
			return current
		elif not root.right:
			current = root.left
			root = None
			return current
		succParent = root
		succ = root.right
		while succ.left != None:
			succParent = succ
			succ = succ.left
		if succParent != root:
			succParent.left = succ.right
		else:
			succParent.right = succ.right
		root.data = succ.data
	return root

