def smart(n, k):
	if n < 5:
		return naive(n, k)
	half = n // 2
	h = half
	H = half + 1
	if not n & 1:
		if k > 1:
			return -1
		perm = [None] * n
		if k == 0:
			perm[::2] = range(h - 1, -1, -1)
			perm[1::2] = range(n - 1, h - 1, -1)
		else:
			perm[::2] = range(h, n)
			perm[1::2] = range(h)
		return perm
	low = h + 3 << h - 2
	lowmid = 1 << h - 1
	if k >= (low + lowmid) * 2:
		return -1
	if k >= low + lowmid:
		merp = smart(n, (low + lowmid) * 2 - 1 - k)
		if merp == -2:
			return merp
		return [n - 1 - m for m in merp]
	if k >= low:
		return binary(list(range(n)), k - low, h)
	offset = [2]
	for i in range(half - 1):
		offset.append(offset[-1] * 2 + (1 << i))
		if offset[-1] > 10 ** 30:
			break
	offset.append(offset[-1] + (1 << i + 1))
	offset.append(0)
	nums = list(range(n))
	perm = []
	pops = 0
	while True:
		if k < 2:
			add = h + k
			return perm + [nums[i * add % n] for i in range(n)]
		i = bisect(offset, k)
		k -= offset[i - 1]
		if k >= offset[i - 1]:
			return perm + binary(nums, k - offset[i - 1], i)
		perm += (nums.pop(i), nums.pop(i + h - 1))
		n -= 2
		half -= 1
		h -= 1
		H -= 1
		if pops:
			popdistr[pops] -= 1
		pops += 1
		popdistr[pops] += 1

def binary(nums, k, i):
	n = len(nums)
	half = n // 2
	H = half + 1
	perm = [None] * n
	(ks, testbit) = (bin(k)[:1:-1], half - 1)
	(left, right) = (0, n - 1)
	for m in range(i, i + half):
		if testbit < len(ks) and ks[testbit] == '1':
			perm[right] = nums[m]
			perm[right - 1] = nums[(m + H) % n]
			right -= 2
		else:
			perm[left] = nums[m]
			perm[left + 1] = nums[(m + H) % n]
			left += 2
		testbit -= 1
	perm[left] = nums[i + half]
	return perm
