	total_sum = 0
	product_sum = 0
	if n == 1:
		return 0
	for i in range(n):
		total_sum += a[i]
		product_sum += a[i] * i
	max_product = product_sum
	for i in range(n - 1, -1, -1):
		product_sum = product_sum + total_sum - a[i] * n
