class Solution:

	def isCyclicHelper(self, si, adj, visited, parent):
		visited[si] = True
		for i in adj[si]:
			if visited[i] is False:
				if self.isCyclicHelper(i, adj, visited, si):
					return True
			elif visited[i] is True and i != parent:
