		if A == B:
			S = set(map(int, str(A * N)))
			return int(C in S or D in S)
		res = 0
		for x in range(N + 1):
			y = N - x
			S = set(map(int, str(A * x + B * y)))
			if C in S or D in S:
				res = (res + Solution.fact[N] * Solution.inv_fact[x] * Solution.inv_fact[y]) % Solution.MOD
		return res

