class Main:

	def __init__(self):
		self.buff = None
		self.index = 0

	def next(self):
		if self.buff is None or self.index == len(self.buff):
			self.buff = sys.stdin.readline().split()
			self.index = 0
		val = self.buff[self.index]
		self.index += 1
		return val

	def next_int(self):
		return int(self.next())

	def cal(self, s):
		if len(s) == 1:
			return s[0]
		if s[0] == 0:
			return self.cal(s[1:])
		v = 1
		for c in s:
			v *= c
		return v

	def q(self, x1, y1, x2, y2):
		print('? {} {} {} {}'.format(x1, y1, x2, y2))
		sys.stdout.flush()
		return self.next_int()

	def ans(self, rs):
		print('! {} {} {} {}'.format(rs[0][0], rs[0][1], rs[1][0], rs[1][1]))
		sys.stdout.flush()

	def f(self, c, n):
		low = 1
		high = n
		while high > low:
			mid = (high + low) // 2
			if self.q(c, low, c, mid) % 2 == 1:
				high = mid
			else:
				low = mid + 1
		return (c, low)

	def g(self, c, n):
		low = 1
		high = n
		while high > low:
			mid = (high + low) // 2
			if self.q(low, c, mid, c) % 2 == 1:
				high = mid
			else:
				low = mid + 1
		return (low, c)

	def solve(self):
		n = self.next_int()
		rs = []
		for i in range(0, n):
			if self.q(i + 1, 1, i + 1, n) % 2 == 1:
				rs.append(self.f(i + 1, n))
			if len(rs) == 2:
				self.ans(rs)
				return
		for i in range(0, n - 1):
			if self.q(1, i + 1, n, i + 1) % 2 == 1:
				rs.append(self.g(i + 1, n))
			if len(rs) == 2:
				self.ans(rs)
				return
		rs.append(self.g(n, n))
		if len(rs) == 2:
			self.ans(rs)
