	def maxIncreaseKeepingSkyline(self, grid: List[List[int]]) -> int:
		INF = -10000
		n = len(grid)
		total = 0
		max_rows = [max(row, default=INF) for row in grid]
		max_cols = [max(col, default=INF) for col in zip(*grid)]
