class Solution:

	def kthLargest(self, k, arr, n):
		if k == 1:
			return arr
		res = [-1] * (k - 1)
		heap = []
		for elm in arr:
			if len(heap) < k:
				heappush(heap, elm)
			else:
				res.append(heap[0])
				if elm > heap[0]:
					heappop(heap)
					heappush(heap, elm)
		else:
			res.append(heap[0])
		return res

