	def minCut(self, source, sink):
		parent = [-1] * self.ROW
		max_flow = 0
		s = -1
		while self.BFS(source, sink, parent):
			path_flow = float('Inf')
			s = sink
			while s != source:
				path_flow = min(path_flow, self.graph[parent[s]][s])
				s = parent[s]
			max_flow += path_flow
			v = sink
			while v != source:
				u = parent[v]
