from typing import List

class Solution:

	def buyMaximumProducts(self, n: int, k: int, price: List[int]) -> int:
		prices = [(val, i) for (i, val) in enumerate(price, start=1)]
		prices.sort(key=lambda x: (x[0], -x[1]))
		cnt = 0
		for (val, i) in prices:
			if i * val <= k:
				cnt += i
				k -= i * val
			else:
				temp = k // val
				k -= temp * val
				cnt += temp
			if k == 0:
				break
		return cnt

