def failure(pat):
	(i, target, n) = (1, 0, len(pat))
	res = [0]
	while i < n:
		if pat[i] == pat[target]:
			target += 1
			res.append(target)
			i += 1
		elif target:
			target = res[target - 1]
		else:
			res.append(0)
			i += 1
	return res

