class Solution:

	def maxSumIS(self, Arr, n):
		T = [Arr[i] for i in range(n)]
		for i in range(1, n):
			for j in range(i):
				if Arr[j] < Arr[i]:
					T[i] = max(T[i], T[j] + Arr[i])
		ans = T[0]
		for i in range(1, n):
			if T[i] > ans:
				ans = T[i]
		return ans

