class Solution:

	def sumBitDifferences(self, arr, n):
		n = len(arr)
		sum_bit_diff = 0
		for i in range(32):
			count_set_bits = 0
			count_clear_bits = 0
			for j in range(n):
				if arr[j] & 1 << i:
					count_set_bits += 1
				else:
