class Solution:

	def max_xor(self, arr, n):
		try:
			l = int(log(max(arr), 2))
		except:
			l = 1
		(mask, res) = (0, 0)
		for i in range(l, -1, -1):
			mask |= 1 << i
			S = set((mask & num for num in arr))
			temp = res | 1 << i
			for num in S:
				if num ^ temp in S:
					res = temp
					break
		return res

